:"The branch checked out there, or `HEAD` when detached.","type":"string"},"path":{"type":"string"}},"required":["path","branch"],"type":"object"}},"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"thread":{"$ref":"#/$defs/Thread"}},"required":["thread"],"title":"ThreadStartResponse","type":"object"}},"turn/enqueue":{"params":{"$schema":"https://json-schema.org/draft/2020-12/schema","description":"`turn/enqueue`: queue a prompt for after the reply in flight.","properties":{"text":{"type":"string"},"threadId":{"type":"string"}},"required":["threadId","text"],"title":"TurnEnqueueParams","type":"object"},"response":{"$schema":"https://json-schema.org/draft/2020-12/schema","description":"One prompt waiting its turn: what the user typed while a reply was still being written.","properties":{"at":{"default":0,"description":"When it was queued, by the server's clock.","format":"int64","type":"integer"},"id":{"type":"string"},"text":{"type":"string"}},"required":["id","text"],"title":"QueueItem","type":"object"}},"turn/interrupt":{"params":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"threadId":{"type":"string"}},"required":["threadId"],"title":"ThreadIdParams","type":"object"},"response":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Empty","type":"object"}},"turn/queue/edit":{"params":{"$schema":"https://json-schema.org/draft/2020-12/schema","description":"`turn/queue/edit`: rewrite a prompt that has not been sent yet.\n\nThe row keeps its id and its place, so a queue whose neighbour was edited is still the\nqueue the user arranged. A prompt the server has already taken off the queue cannot be\nedited — it is being sent, and the answer would contradict what the model was given.","properties":{"itemId":{"type":"string"},"text":{"type":"string"},"threadId":{"type":"string"}},"required":["threadId","itemId","text"],"title":"QueueEditParams","type":"object"},"response":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Empty","type":"object"}},"turn/queue/remove":{"params":{"$schema":"https://json-schema.org/draft/2020-12/schema","description":"One queued prompt by id, for `turn/queue/remove`, `turn/queue/edit` and\n`turn/queue/sendNow`.","properties":{"itemId":{"type":"string"},"threadId":{"type":"string"}},"required":["threadId","itemId"],"title":"QueueItemParams","type":"object"},"response":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Empty","type":"object"}},"turn/queue/reorder":{"params":{"$schema":"https://json-schema.org/draft/2020-12/schema","description":"`turn/queue/reorder`: the queue's whole new order.\n\nThe whole list rather than a move, because that is what a drag produces and because it\nmakes a stale client harmless: an id that is no longer queued is skipped, and one the\ncaller did not name keeps its place at the end instead of disappearing.","properties":{"itemIds":{"items":{"type":"string"},"type":"array"},"threadId":{"type":"string"}},"required":["threadId","itemIds"],"title":"QueueReorderParams","type":"object"},"response":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Empty","type":"object"}},"turn/queue/resume":{"params":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"threadId":{"type":"string"}},"required":["threadId"],"title":"ThreadIdParams","type":"object"},"response":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Empty","type":"object"}},"turn/queue/sendNow":{"params":{"$schema":"https://json-schema.org/draft/2020-12/schema","description":"One queued prompt by id, for `turn/queue/remove`, `turn/queue/edit` and\n`turn/queue/sendNow`.","properties":{"itemId":{"type":"string"},"threadId":{"type":"string"}},"required":["threadId","itemId"],"title":"QueueItemParams","type":"object"},"response":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Empty","type":"object"}},"turn/rewind":{"params":{"$schema":"https://json-schema.org/draft/2020-12/schema","description":"`turn/rewind`: run the conversation again from one of its turns — the reply to it is thrown\naway and asked for once more, or (with `text`) the user's words are replaced first.\n\n`turn_id` names the turn to run *again*, so a retry names the last one and an edit names the\none being corrected. Everything after it is dropped from the history; the transcript keeps\nthe lines and records a rewind marker, so nothing is destroyed on disk.","properties":{"rewindFiles":{"default":false,"description":"Put the workspace back to how it was before that turn's run first.\n\nA retry that leaves the tree alone re-runs the prompt against code the abandoned attempt\nalready changed — it reads files the first run edited, or its patch finds the change\nalready applied and does nothing. Both are silent. The caller asks the user, so this is\nnever implied: `false` means \"keep my files\", which is what someone repeating a prompt\nafter their own edits wants.","type":"boolean"},"text":{"default":null,"description":"Replacement words for that turn; absent keeps the ones it already has (a retry).","type":["string","null"]},"threadId":{"type":"string"},"turnId":{"type":"string"}},"required":["threadId","turnId"],"title":"TurnRewindParams","type":"object"},"response":{"$defs":{"FilesRewound":{"description":"What `turn/rewind` did to the workspace, so the client can report it honestly.","properties":{"hadCheckpoint":{"description":"Whether a checkpoint existed at all: a turn that changed nothing, or a workspace that is\nnot a git repository, has nothing to put back.","type":"boolean"},"removed":{"description":"Files the turn created, now removed.","format":"uint","minimum":0,"type":"integer"},"restored":{"description":"Files written back to their pre-turn content.","format":"uint","minimum":0,"type":"integer"},"skipped":{"default":[],"description":"Paths that could not be put back, with the reason.","items":{"$ref":"#/$defs/SkippedPath"},"type":"array"}},"r