/// A schema error raised before a native frame is sent or accepted.
class NativeProtocolSchemaError extends FormatException {
  NativeProtocolSchemaError(this.method, this.direction, String message)
      : super(message);

  final String method;
  final String direction;

  @override
  String toString() =>
      'NativeProtocolSchemaError($method.$direction): $message';
}

/// Schema metadata and validation generated from the native protocol snapshot.
abstract final class NativeProtocolSchema {
  static Map<String, Object?>? _decoded;

  static Map<String, Object?> get methods {
    return _decoded ??=
        (jsonDecode(nativeProtocolMethodSchemasJson) as Map).cast<String, Object?>();
  }

  static bool hasMethod(String method) => methods.containsKey(method);

  static Map<String, Object?> method(String method) {
    final value = methods[method];
    if (value is! Map) {
      throw ArgumentError.value(method, 'method', 'Unknown native method');
    }
    return value.cast<String, Object?>();
  }

  static void validateParams(String methodName, Object? value) =>
      _validate(methodName, 'params', method(methodName)['params'], value);

  static void validateResponse(String methodName, Object? value) =>
      _validate(methodName, 'response', method(methodName)['response'], value);

  static void _validate(
    String methodName,
    String direction,
    Object? rawSchema,
    Object? value,
  ) {
    try {
      _check(rawSchema, value, methodName, direction, rawSchema);
    } on _SchemaMismatch catch (error) {
      throw NativeProtocolSchemaError(methodName, direction, error.message);
    }
  }

  static void _check(
    Object? rawSchema,
    Object? value,
    String methodName,
    String direction,
    Object? rawRoot,
  ) {
    if (rawSchema is! Map) {
      throw _SchemaMismatch('schema is not an object');
    }
    final schema = rawSchema.cast<String, Object?>();
    final reference = schema['\$ref'];
    if (reference is String) {
      final root = rawRoot is Map ? rawRoot.cast<String, Object?>() : null;
      final definitions = root?['\$defs'];
      final name = reference.split('/').last;
      final resolved = definitions is Map ? definitions[name] : null;
      if (resolved == null) throw _SchemaMismatch('unresolved reference $reference');
      _check(resolved, value, methodName, direction, rawRoot);
      return;
    }

    for (final key in const <String>['anyOf', 'oneOf']) {
      final alternatives = schema[key];
      if (alternatives is List) {
        for (final alternative in alternatives) {
          try {
            _check(alternative, value, methodName, direction, rawRoot);
            return;
          } on _SchemaMismatch {
            // Try the next branch.
          }
        }
        throw _SchemaMismatch('does not match $key');
      }
    }

    final constant = schema['const'];
    if (constant != null && !_sameJson(constant, value)) {
      throw _SchemaMismatch('must equal $constant');
    }
    final enumeration = schema['enum'];
    if (enumeration is List && !enumeration.any((item) => _sameJson(item, value))) {
      throw _SchemaMismatch('must be one of $enumeration');
    }

    final type = schema['type'];
    if (type is List) {
      if (!type.any((candidate) => _matchesType(candidate, value))) {
        throw _SchemaMismatch('has type ${_typeName(value)}, expected $type');
      }
    } else if (type is String && !_matchesType(type, value)) {
      throw _SchemaMismatch('has type ${_typeName(value)}, expected $type');
    }

    if (type == 'object' || schema['properties'] is Map || schema['required'] is List) {
      if (value is! Map) throw _SchemaMismatch('must be an object');
      final object = value.cast<Object?, Object?>();
      final required = schema['required'];
      if (required is List) {
        for (final name in required.whereType<String>()) {
          if (!object.containsKey(name)) throw _SchemaMismatch('missing required field $name');
        }
      }
      final properties = schema['properties'];
      if (properties is Map) {
        for (final entry in properties.entries) {
          if (object.containsKey(entry.key)) {
            _check(entry.value, object[entry.key], methodName, direction, rawRoot);
          }
        }
      }
    }

    if (type == 'array' || schema['items'] != null) {
      if (value is! List) throw _SchemaMismatch('must be an array');
      final itemSchema = schema['items'];
      if (itemSchema != null) {
        for (final item in value) {
          _check(itemSchema, item, methodName, direction, rawRoot);
        }
      }
    }
  }

  static bool _matchesType(Object? type, Object? value) {
    switch (type) {
      case 'object':
        return value is Map;
      case 'array':
        return value is List;
      case 'string':
        return value is String;
      case 'integer':
        return value is int;
      case 'number':
        return value is num;
      case 'boolean':
        return value is bool;
      case 'null':
        return value == null;
      default:
        return true;
    }
  }

  static String _typeName(Object? value) {
    if (value == null) return 'null';
    if (value is Map) return 'object';
    if (value is List) return 'array';
    if (value is String) return 'string';
    if (value is bool) return 'boolean';
    if (value is int) return 'integer';
    if (value is num) return 'number';
    return value.runtimeType.toString();
  }

  static bool _sameJson(Object? left, Object? right) {
    if (left is Map && right is Map) {
      if (left.length != right.length) return false;
      for (final entry in left.entries) {
        if (!right.containsKey(entry.key) || !_sameJson(entry.value, right[entry.key])) {
          return false;
        }
      }
      return true;
    }
    if (left is List && right is List) {
      return left.length == right.length &&
          List.generate(left.length, (index) => _sameJson(left[index], right[index]))
              .every((same) => same);
    }
    return left == right;
  }
}

class _SchemaMismatch implements Exception {
  const _SchemaMismatch(this.message);
  final String message;
}
